def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Create a 2D array to store maximum happiness values
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Iterate through each item and budget to fill the dp array
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        for j in range(1, n + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - price] + importance)

    # The maximum happiness value that can be achieved is in dp[m][n]
    return dp[m][n]

def max_energy(beads):
    n = len(beads)
    dp = [0] * n
    dp[0] = beads[0]
    for i in range(1, n):
        for j in range(i):
            if beads[j] == beads[i]:
                dp[i] = max(dp[i], dp[j] * beads[i] * beads[(i + 1) % n])
    return max(dp)

