def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    result = []
    for i in range(n, 0, -1):
        coefficient = coeffs[i - 1]
        if coefficient != 0:
            term = ''
            if coefficient == -1:
                term = '-'
            elif coefficient != 1:
                term += str(abs(coefficient))
            if i > 1:
                term += f"x^{i}"
            elif i == 1:
                term += "x"
            result.append(term)
    if result:
        result.reverse()
    return ' + '.join(result)

def decode(encoded: str, original: str, message: str) -> str:
    decoded = str()
    mapping = dict()

    # Step 1: Check if the lengths of encoded, original, and message match
    if len(encoded) != len(original):
        return "Failed"

    # Step 2: Map encoded letters to original letters
    for i in range(len(encoded)):
        if encoded[i] in mapping:
            if mapping[encoded[i]] == original[i]:
                continue
            else:
                return "Failed"
        mapping[encoded[i]] = original[i]

    # Step 3: Decode the message
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        return None  # Handle trivial cases

    largest_factor = None

    # Check for factors from 2 up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            largest_factor = i
            n //= i

    # If n is a prime number greater than 2, it is the largest factor
    if n > 2:
        largest_factor = n

    return largest_factor

def count_partitions(n: int, k: int, x: int) -> int:
    if k == 1:
        return n >= x and 1 or 0
    if n < k * x:
        return 0
    prev_partitions = [0] * (k * x)
    prev_partitions[x - 1] = 1
    for i in range(k - 1, 0, -1):
        current_partitions = [0] * (k * x)
        current_partitions[x - 1] = 1
        for j in range(x, n + 1):
            current_partitions[j - 1] += prev_partitions[j - 1] + prev_partitions[j - k * x]
        prev_partitions = current_partitions
    return prev_partitions[n]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if (n, last) in memo:
        return memo[(n, last)]

    # Base case: if the sequence is just the starting number 'n', there's only one sequence
    if n == last:
        return 1

    # Recursive case: count sequences ending with numbers less than half of 'last'
    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[(n, last)] = count
    return count

