def catalan_number(n: int) -> int:
    if n < 0:
        return 0
    if n == 0 or n == 1:
        return 1

    catalan = [0] * (n + 1)
    catalan[0] = catalan[1] = 1

    for i in range(2, n + 1):
        catalan[i] = sum(catalan[j - 1] * catalan[i - j] for j in range(1, i + 1))

    return catalan[n]

