def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, shift):
        if c.islower():
            return chr((( ord(c) - ord('a') + shift) % 26) + ord('a'))
        elif c.isupper():
            return chr((( ord(c) - ord('A') + shift) % 26) + ord('A'))
        return c

    def decrypt_char(c):
        keyword = key[(key.index(c) - len(key)) % len(key)]
        shift_amount = ord(keyword) - ord('A')
        return shift_char(c, shift_amount)

    return ''.join(decrypt_char(c) for c in ciphertext)

def mod_inverse(a, b):
    if b == 1:
        return 0  # If b is 1, the multiplicative inverse is always 0
    x0, x1 = 1, 0
    y0, y1 = 0, 1

    while a != 1:
        q, r = b // a, b % a  # Calculate quotient and remainder
        b, a = a, r        # Swap values
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1

