def minimum_students_to_leave(heights):
    n = len(heights)
    if n < 3:
        return 0

    left = n - 1
    right = 0
    common_height = heights[left]
    students_to_leave = 0

    while left >= 1 and right < n:
        if heights[left] >= common_height and heights[right] <= common_height:
            break
        students_to_leave += min(left, n - right)
        left -= 1
        right += 1

    if left == 0:
        return left + n - right
    else:
        return students_to_leave + left + n - right

